use std::f64::consts::PI;

use fj::core::{
    math::Vector,
    operations::{
        build::{BuildCycle, BuildRegion, BuildSketch},
        reverse::Reverse,
        sweep::SweepSketch,
        update::{UpdateRegion, UpdateSketch},
    },
    topology::{Cycle, Region, Sketch, Solid},
};

pub fn model(
    num_points: u64,
    r1: f64,
    r2: f64,
    h: f64,
    core: &mut fj::core::Core,
) -> Solid {
    let num_vertices = num_points * 2;
    let vertex_iter = (0..num_vertices).map(|i| {
        let angle_rad = 2. * PI / num_vertices as f64 * i as f64;
        let radius = if i % 2 == 0 { r1 } else { r2 };
        (angle_rad, radius)
    });

    let mut outer_points = Vec::new();
    let mut inner_points = Vec::new();

    for (angle_rad, radius) in vertex_iter {
        let (sin, cos) = angle_rad.sin_cos();

        let x = cos * radius;
        let y = sin * radius;

        outer_points.push([x, y]);
        inner_points.push([x / 2., y / 2.]);
    }

    let bottom_surface = core.layers.topology.surfaces.xy_plane();
    let sweep_path = Vector::from([0., 0., -h]);

    Sketch::empty(&core.layers.topology)
        .add_regions(
            [Region::polygon(
                outer_points,
                core.layers.topology.surfaces.space_2d(),
                core,
            )
            .add_interiors(
                [Cycle::polygon(
                    inner_points,
                    core.layers.topology.surfaces.space_2d(),
                    core,
                )
                .reverse(core)],
                core,
            )],
            core,
        )
        .sweep_sketch(bottom_surface, sweep_path, core)
}

use fj::core::{
    math::{Point, Vector},
    operations::{
        build::{BuildCycle, BuildRegion, BuildSketch},
        reverse::Reverse,
        sweep::SweepSketch,
        update::{UpdateRegion, UpdateSketch},
    },
    topology::{Cycle, Region, Sketch as SketchOld, Solid},
};

pub fn model_old(
    outer_radius: f64,
    inner_radius: f64,
    height: f64,
    core: &mut fj::core::Core,
) -> Solid {
    let bottom_surface = core.layers.topology.surfaces.xy_plane();
    let sweep_path = Vector::from([0., 0., -height]);

    SketchOld::empty(&core.layers.topology)
        .add_regions(
            [Region::circle(
                Point::origin(),
                outer_radius,
                core.layers.topology.surfaces.space_2d(),
                core,
            )
            .add_interiors(
                [Cycle::circle(
                    Point::origin(),
                    inner_radius,
                    core.layers.topology.surfaces.space_2d(),
                    core,
                )
                .reverse(core)],
                core,
            )],
            core,
        )
        .sweep_sketch(bottom_surface, sweep_path, core)
}

